<x-filament-panels::page>
    <style>
        .orion-inv-form{direction:rtl;--if-panel:#0d1728;--if-panel2:#111c30;--if-border:#263853;--if-soft:#1b2a41;--if-text:#f8fafc;--if-muted:#8091aa;--if-purple:#8b5cf6;--if-green:#34d399;--if-amber:#fbbf24;--if-blue:#60a5fa;--if-red:#f87171}.orion-inv-form *{box-sizing:border-box}.if-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:14px}.if-step{position:relative;overflow:hidden;min-height:82px;padding:13px 15px;border:1px solid var(--if-border);border-radius:14px;background:linear-gradient(145deg,var(--if-panel2),#0b1525)}.if-step::after{content:"";position:absolute;right:0;left:0;bottom:0;height:2px;background:linear-gradient(90deg,transparent,var(--accent),transparent);opacity:.75}.if-step-top{display:flex;justify-content:space-between;align-items:center;gap:8px}.if-step-no{width:25px;height:25px;display:flex;align-items:center;justify-content:center;border-radius:8px;border:1px solid color-mix(in srgb,var(--accent) 35%,#31435f);background:color-mix(in srgb,var(--accent) 8%,#0f192b);color:var(--accent);font-size:9px;font-weight:950}.if-step-title{color:#dce5f1;font-size:10px;font-weight:900}.if-step-note{margin-top:8px;color:#687a93;font-size:8px;line-height:1.6}.if-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:14px;align-items:start}.if-shell,.if-card{border:1px solid var(--if-border);border-radius:16px;background:linear-gradient(145deg,#0d1728,#091321);box-shadow:0 16px 38px rgba(0,0,0,.14)}.if-shell{overflow:hidden}.if-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 17px;border-bottom:1px solid var(--if-soft);background:#0f192b}.if-title{font-size:15px;font-weight:950;color:var(--if-text)}.if-sub{margin-top:3px;font-size:9px;color:#6b7d96}.if-status{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border:1px solid rgba(96,165,250,.18);border-radius:999px;background:rgba(96,165,250,.055);color:#93c5fd;font-size:9px;font-weight:900}.if-status::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--if-blue)}.if-form{padding:16px}.if-actions{margin-top:16px;padding-top:14px;border-top:1px solid var(--if-soft)}.if-side{display:grid;gap:12px;position:sticky;top:16px}.if-card{padding:15px}.if-kicker{font-size:8px;letter-spacing:.08em;color:#7d6ab0;font-weight:950;direction:ltr;text-align:right}.if-card-title{margin-top:5px;color:#f5f8fc;font-size:14px;font-weight:950}.if-text{margin-top:8px;color:#71829b;font-size:9px;line-height:1.8}.if-checks{margin-top:12px;border-top:1px solid #1b2a41}.if-check{display:flex;gap:8px;padding:10px 0;border-bottom:1px solid #17243a}.if-check:last-child{border-bottom:0}.if-dot{width:7px;height:7px;margin-top:5px;border-radius:50%;background:var(--dot);flex:0 0 auto}.if-check strong{display:block;color:#dce5f1;font-size:9px}.if-check span{display:block;margin-top:2px;color:#687990;font-size:8px;line-height:1.6}.if-tip{border-color:rgba(251,191,36,.2);background:linear-gradient(145deg,rgba(251,191,36,.055),#0b1525)}.if-tip strong{color:#f6d988;font-size:10px}.if-tip p{margin:7px 0 0;color:#8b8066;font-size:8px;line-height:1.8}.orion-inv-form .fi-sc-section{border:1px solid #22334d!important;border-radius:13px!important;background:#0f192b!important;box-shadow:none!important;overflow:hidden;margin-bottom:12px!important}.orion-inv-form .fi-sc-section-header{background:#111c30!important;border-bottom:1px solid #1e2d45!important;padding:12px 14px!important}.orion-inv-form .fi-sc-section-header-heading{color:#f3f6fb!important;font-size:11px!important;font-weight:950!important}.orion-inv-form .fi-sc-section-content{padding:14px!important}.orion-inv-form .fi-fo-field-wrp-label span{font-size:9px!important;font-weight:850!important;color:#9fafc3!important}.orion-inv-form .fi-input-wrp{border-color:#2a3b56!important;background:#0b1525!important;border-radius:9px!important;box-shadow:none!important}.orion-inv-form .fi-input-wrp:focus-within{border-color:var(--if-purple)!important;box-shadow:0 0 0 1px rgba(139,92,246,.18)!important}.orion-inv-form .fi-input,.orion-inv-form .fi-select-input{font-size:10px!important;color:#eef3f8!important}.orion-inv-form .fi-fo-repeater-item{border-color:#263853!important;background:#0c1627!important;border-radius:12px!important}@media(max-width:1100px){.if-layout{grid-template-columns:1fr}.if-side{position:static;grid-template-columns:repeat(2,1fr)}.if-steps{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.if-steps,.if-side{grid-template-columns:1fr}.if-head{align-items:flex-start;flex-direction:column}}
    </style>
    <div class="orion-inv-form">
        <div class="if-steps"><div class="if-step" style="--accent:var(--if-blue)"><div class="if-step-top"><span class="if-step-title">بيانات الفاتورة</span><span class="if-step-no">01</span></div><div class="if-step-note">النوع والطرف والتاريخ وطريقة الدفع</div></div><div class="if-step" style="--accent:var(--if-purple)"><div class="if-step-top"><span class="if-step-title">الأصناف والأسعار</span><span class="if-step-no">02</span></div><div class="if-step-note">الكميات والأسعار والخصومات على مستوى البنود</div></div><div class="if-step" style="--accent:var(--if-green)"><div class="if-step-top"><span class="if-step-title">الضريبة والإجماليات</span><span class="if-step-no">03</span></div><div class="if-step-note">VAT والإجمالي والمدفوع والمتبقي</div></div><div class="if-step" style="--accent:var(--if-amber)"><div class="if-step-top"><span class="if-step-title">المراجعة والحفظ</span><span class="if-step-no">04</span></div><div class="if-step-note">راجع الحالة قبل التأكيد والترحيل</div></div></div>
        <div class="if-layout"><div class="if-shell"><div class="if-head"><div><div class="if-title">إنشاء فاتورة جديدة</div><div class="if-sub">بيع أو شراء أو مرتجع من نفس المركز</div></div><span class="if-status">فاتورة جديدة</span></div><form wire:submit="create" class="if-form">{{ $this->form }}<div class="if-actions"><x-filament::actions :actions="$this->getFormActions()" /></div></form></div><aside class="if-side"><div class="if-card"><div class="if-kicker">INVOICE CHECKLIST</div><div class="if-card-title">قبل حفظ الفاتورة</div><div class="if-text">اختيار النوع الصحيح مهم لأنه يحدد السعر الافتراضي واتجاه المخزون والمعالجة المحاسبية.</div><div class="if-checks"><div class="if-check"><span class="if-dot" style="--dot:var(--if-blue)"></span><div><strong>نوع الفاتورة</strong><span>بيع، شراء، مرتجع بيع أو مرتجع شراء.</span></div></div><div class="if-check"><span class="if-dot" style="--dot:var(--if-purple)"></span><div><strong>الطرف والمخزن</strong><span>حدد العميل أو المورد والمخزن المرتبط بالحركة.</span></div></div><div class="if-check"><span class="if-dot" style="--dot:var(--if-green)"></span><div><strong>الضريبة والأسعار</strong><span>راجع سعر الوحدة والخصم ونسبة VAT لكل بند.</span></div></div><div class="if-check"><span class="if-dot" style="--dot:var(--if-amber)"></span><div><strong>الدفع والحالة</strong><span>المبلغ المدفوع والمتبقي والحالة تؤثر على المتابعة المالية.</span></div></div></div></div><div class="if-card if-tip"><strong>مهم</strong><p>منطق تحديث المخزون وإنشاء القيود المحاسبية موجود بالفعل في النظام. التصميم الجديد لا يغيّر هذا المنطق.</p></div></aside></div>
    </div>
</x-filament-panels::page>
